#include "field.hpp"
using Clock=std::chrono::steady_clock;
bool par(U x){return (__builtin_popcountll(uint64_t(x))^__builtin_popcountll(uint64_t(x>>64)))&1;}
struct Span{int n,rank=0;std::array<U,128>b{};Span(int nn):n(nn){};U rem(U x)const{for(int i=n-1;i>=0;i--)if(((x>>i)&1)&&b[i])x^=b[i];return x;}void add(U x){x=rem(x);if(x){b[degree(x)]=x;rank++;}}U dual(U rhs)const{U r=rem(rhs);if(!r)return 0;int k=degree(r);U l=0;for(int i=0;i<n;i++)if((rem(U(1)<<i)>>k)&1)l|=U(1)<<i;return l;}};
std::vector<U> nullspace(int n,std::vector<U> rows){int r=0;std::vector<int>piv;for(int j=0;j<n;j++){int z=r;while(z<int(rows.size())&&!((rows[z]>>j)&1))z++;if(z==int(rows.size()))continue;std::swap(rows[r],rows[z]);for(int i=0;i<int(rows.size());i++)if(i!=r&&((rows[i]>>j)&1))rows[i]^=rows[r];piv.push_back(j);r++;}std::set<int>ps(piv.begin(),piv.end());std::vector<U>out;for(int j=0;j<n;j++)if(!ps.count(j)){U v=U(1)<<j;for(int i=0;i<r;i++)if((rows[i]>>j)&1)v|=U(1)<<piv[i];for(U row:rows)assert(!par(row&v));out.push_back(v);}return out;}
struct Cell{U p,s,l;std::vector<U>vs;};
Cell build(const F&f,int d,U p,U s){std::vector<U>qs;Span a(f.n);for(int i=0;i<d;i++){U t=U(1)<<i,q=f.sq(t)^f.mul(p,t);qs.push_back(q);a.add(f.sq(q)^f.mul(s,q));}U rhs=1^f.mul(f.sq(s),f.sq(p)),l=a.dual(rhs);Cell c{p,s,l,{}};if(!l)return c;assert(par(l&rhs));std::vector<U>rows;for(U q:qs){U row=0;assert(!par(l&(f.sq(q)^f.mul(s,q))));for(int j=0;j<f.n;j++)if(par(l&f.mul(q,U(1)<<j)))row|=U(1)<<j;rows.push_back(row);}U row=0;for(int j=0;j<f.n;j++)if(par(l&f.mul(f.sq(U(1)<<j),f.sq(p))))row|=U(1)<<j;rows.push_back(row);c.vs=nullspace(f.n,rows);assert(int(c.vs.size())>=f.n-d-(p==0));for(U v:c.vs){for(U q:qs)assert(!par(l&f.mul(v,q)));assert(!par(l&f.mul(f.sq(v),f.sq(p))));}return c;}
U rawmul(U a,U b,int n,U mod){U r=0;for(int i=0;i<n;i++)if((b>>i)&1)r^=a<<i;for(int i=2*n-2;i>=n;i--)if((r>>i)&1)r^=mod<<(i-n);return r;}
bool literal(U x,U y,U s,int n,U mod){auto m=[&](U a,U b){return rawmul(a,b,n,mod);};U a=m(x,y),b=m(x,s),c=m(y,s);return (m(a,a)^m(b,b)^m(c,c)^m(a,s)^1)==0;}
void run(const std::string&id){unsigned small=0,points=0;for(auto cfg:std::vector<std::array<int,3>>{{3,11,2},{4,19,2},{5,37,3},{7,131,3}}){int n=cfg[0],d=cfg[2];U mod=cfg[1];F f(n,mod);assert(f.irreducible());for(int p=0;p<(1<<d);p++)for(int s=0;s<(1<<n);s++){auto c=build(f,d,p,s);if(!c.l)continue;small++;for(unsigned k=0;k<(1u<<c.vs.size());k++){U v=s;for(size_t j=0;j<c.vs.size();j++)if((k>>j)&1)v^=c.vs[j];points++;for(int x=0;x<(1<<d);x++)assert(!literal(x,x^p,v,n,mod));}}}
F f(83,hex("800000000200000000007"));assert(f.irreducible());std::ostringstream cells;bool first=true;unsigned count=0,mindim=83,maxdim=0;for(U p:std::vector<U>{0,1,2,3,0x12345,0x3ffff})for(U s:std::vector<U>{0,1,hex("622425e96ba633969263b")}){auto c=build(f,18,p,s);if(!c.l)continue;count++;mindim=std::min(mindim,unsigned(c.vs.size()));maxdim=std::max(maxdim,unsigned(c.vs.size()));if(!first)cells<<",";first=false;cells<<"{\"p\":\""<<hx(p)<<"\",\"center\":\""<<hx(s)<<"\",\"lambda\":\""<<hx(c.l)<<"\",\"dimension\":"<<c.vs.size()<<",\"basis\":[";for(size_t j=0;j<c.vs.size();j++){if(j)cells<<",";cells<<"\""<<hx(c.vs[j])<<"\"";}cells<<"]}";}
assert(count&&maxdim>=65);std::cout<<"{\"schema\":\"scientific_result_v1\",\"experiment_id\":\""<<id<<"\",\"status\":\"passed\",\"summary\":\"Adaptive nullspace directions yield replayable large empty pair cells; no full-chain completeness or speed ratio.\",\"evidence\":{\"small_certified_cells\":"<<small<<",\"small_member_checks\":"<<points<<",\"wide_certified_cells\":"<<count<<",\"minimum_dimension\":"<<mindim<<",\"maximum_dimension\":"<<maxdim<<",\"cells\":["<<cells.str()<<"],\"original_hard_root_count_exact\":null,\"qualified_speedup\":null,\"release_gate_claim\":false},\"next_actions\":[\"Measure overlap and residual outer pair-sum coverage; prove full controller coverage before another hard solve.\"]}\n";}
int main(int argc,char**argv){assert(argc==2);auto start=Clock::now();std::ostringstream buf;auto*old=std::cout.rdbuf(buf.rdbuf());run(argv[1]);std::cout.rdbuf(old);auto out=buf.str();if(std::chrono::duration<double>(Clock::now()-start).count()>65)return 3;std::cout<<out;}
